public class Onibus extends MeioTransporte { private final int numeroLinha; public Onibus(int numeroLinha,int capacidade,double velocidade){super(capacidade,velocidade);this.numeroLinha=numeroLinha;} @Override public void mover(double distancia){double tempo=distancia/(velocidadeMaxima*0.8);System.out.printf("Ônibus linha %d: %.1f horas%n",numeroLinha,tempo);} public void anunciarParada(String parada){System.out.println("Próxima parada: "+parada);} }
